#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_ADDRESS 0x3C   // Если не работает — поменяй на 0x3D

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

const int charW = 6;    // ширина символа при textSize(1)
const int charH = 8;    // высота символа
const int cols = SCREEN_WIDTH / charW;  // 21 символ в строку

// Виртуальный "холст" — массив строк текста
const int MAX_LINES = 30;
char lines[MAX_LINES][cols + 1];  // +1 под нуль-терминатор
int lineCount = 0;

// Добавление строки в виртуальный холст
void addLine(const char* text) {
  if (lineCount < MAX_LINES) {
    strncpy(lines[lineCount], text, cols);
    lines[lineCount][cols] = '\0';
    lineCount++;
  }
}

// Разбиваем последовательность символов на строки по `cols` штук
void addCharRange(int startCode, int endCode, const char* label) {
  if (label) addLine(label);
  char buf[cols + 1];
  int pos = 0;

  for (int code = startCode; code <= endCode; code++) {
    buf[pos++] = (char)code;
    if (pos >= cols) {
      buf[pos] = '\0';
      addLine(buf);
      pos = 0;
    }
  }
  if (pos > 0) {
    buf[pos] = '\0';
    addLine(buf);
  }
}

// Отрисовка виртуального холста со смещением yOffset
void drawWithOffset(int yOffset) {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);

  for (int i = 0; i < lineCount; i++) {
    int y = i * charH + yOffset;
    // Рисуем только видимые строки
    if (y > -charH && y < SCREEN_HEIGHT) {
      display.setCursor(0, y);
      display.print(lines[i]);
    }
  }

  display.display();
}

void setup() {
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDRESS)) {
    for (;;);  // Дисплей не найден — зависаем
  }

  // --- Заполняем виртуальный холст ---
  addLine("== ALL ASCII 32-126 ==");
  addLine("");

  addCharRange('A', 'Z', "A-Z:");
  addCharRange('a', 'z', "a-z:");
  addCharRange('0', '9', "0-9:");
  addCharRange(32, 47,  "Special 32-47:");   // пробел, !, ", #, $, ...
  addCharRange(58, 64,  "Special 58-64:");   // : ; < = > ?
  addCharRange(91, 96,  "Special 91-96:");   // [ \ ] ^ _
  addCharRange(123, 126, "Special 123-126:"); // { | } ~
}

void loop() {
  int totalHeight = lineCount * charH;
  int maxScroll = totalHeight - SCREEN_HEIGHT;

  // Если всё помещается — просто показываем
  if (maxScroll <= 0) {
    drawWithOffset(0);
    delay(3000);
    return;
  }

  // Плавная прокрутка вниз
  for (int offset = 0; offset >= -maxScroll; offset -= 2) {
    drawWithOffset(offset);
    delay(40);
  }

  // Пауза в нижней точке
  delay(1500);

  // Плавная прокрутка наверх
  for (int offset = -maxScroll; offset <= 0; offset += 2) {
    drawWithOffset(offset);
    delay(40);
  }

  // Пауза в верхней точке
  delay(1500);
}
